/**
 * Canonical, CDN-facing contract for a sealed Craps battle replay.
 *
 * The mutable pointer is deliberately tiny. Everything it discovers is immutable and
 * content-addressed, so a resolved battle can be requested by every open tab without
 * turning the database API into a fan-out service.
 */

import { CHAIN, CONTRACTS } from '../app/chain-config.js';

export const CRAPS_REPLAY_SCHEMA_VERSION = 3;
// 0880d134c: the run-#45 ruleset — the 0..7 chip-board continuum (settlement scatters
// `10 - placed`), the three-chip leg cap, the FIXED 5x scheduled goal, the eight-row
// placed-indexed shooter boost, and the single 250,000/1,200,000 progressive cutoff pair.
// Exact-match checked against `manifest.ruleset.engineVersion`, so bundles from any older
// materializer fail closed here rather than animating the wrong chips.
//
// 635b010a (run #51): the SETTLEMENT arithmetic is byte-identical to a8d068839 — that vendor
// added `upgradeReservedDay` / `convertNormalToHigh`, cut `previewSettlement`, and put the
// seat's high bits on the `CrapsSlipPlaced` echo. None of that is a dice or payout rule. The
// string still moves because it names the AUDIT FREEZE a bundle was materialized under, and
// the two repos must move together: this constant and the database's
// `src/craps/replay-bundle.ts` CRAPS_REPLAY_ENGINE_VERSION are compared for EXACT equality,
// so shipping one without the other fails every replay closed.
//
// 0889affc1 (audit 4f5467962, run #57): the arithmetic moved. `_SLIP_ROLL_BUDGET` 8192 -> 1_000 and
// every seat settles through `CrapsEngine.settleBattle`, which adds awarded jackpot-battle seats
// keyed to their bet id. The run-56 deployment (224de529) still replays under this pin at its own
// 8,192-roll budget (chain/craps.js picks the budget by read schema); its runtime hash stays listed.
//
// e579cd318 (audit 3c79c1486, run #58): the dice are unchanged, the table's payment is not.
// `CrapsBetSettled.won` rides the seat's run capital (`_ride(s.won, _runCapital(...), bankroll)`):
// whole copies everywhere but a jackpot High Roller seat, whose `bankroll + highExtra` arrives as
// the optional `runCapitalWei`; and the retired standing no longer breaks a tie.
//
// 32c604531 (run #59): the arithmetic moved. `_SLIP_ROLL_BUDGET` 1_000 -> 600, and every shooter
// doubles the wager from `_ESC_FAST_FROM` = 30 (it doubled every three before), so every run past
// shooter 30 is charged differently. The replay engine mirrors the new escalator.
//
// eb04b2e80 (audit b05ea7c50, run #64): FLIP has zero decimals. The dice are unchanged; the money
// path is not. `CrapsEngine.settleBattle` takes whole-FLIP bankroll/goal, plays the run in 10^18
// sub-units, ranks on that sub-unit run, then floors `bankrollOut`/`peakBankroll` to whole FLIP
// before the hundreds rounding; every event amount is whole FLIP.
export const CRAPS_REPLAY_ENGINE_VERSION = 'craps-hot12-own30-longest-v5';
export const CRAPS_REPLAY_CDN_PREFIX = '/craps/replays/v1';
export const CRAPS_REPLAY_DEFAULT_SHARD_SIZE = 256;
// Mirrors `Craps._MAX_SLIP_HANDS` and `Craps._SLIP_ROLL_CEILING` (`_SLIP_ROLL_BUDGET - 1 +
// _MAX_ROLLS`). BOTH doubled at the 2026-08-29 re-vendor — the goal now LATCHES and the run plays
// on, so the contract gave it room. Stale here, this validator REJECTS the manifest for any long
