// (224de529) ceiling, 8_192 - 1 + 512; audit 32c604531's 600 budget tops out at 1_111, under it,
// so the bound stays at the larger figure while run 56 is replayable.
export const CRAPS_REPLAY_MAX_HANDS = 512;
